(function(){"use strict";function supportsWebP(){const canvas=document.createElement("canvas");canvas.width=1;canvas.height=1;return canvas.toDataURL("image/webp").indexOf("data:image/webp")===0}const hasWebPSupport=supportsWebP();if(!("IntersectionObserver"in window)){document.querySelectorAll('img[loading="lazy"]').forEach(img=>{loadImage(img)});return}function loadImage(img){if(img.dataset.src){img.src=img.dataset.src}else if(hasWebPSupport&&img.dataset.webp){img.src=img.dataset.webp}img.onload=()=>{img.classList.add("loaded");const placeholder=img.parentElement.querySelector(".img-placeholder");if(placeholder){placeholder.remove()}};img.onerror=()=>{if(hasWebPSupport&&img.dataset.fallback){img.src=img.dataset.fallback}}}const imageObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;loadImage(img);imageObserver.unobserve(img)}})},{rootMargin:"50px 0px",threshold:.01});document.querySelectorAll('img[loading="lazy"]').forEach(img=>{imageObserver.observe(img)});window.addEventListener("load",()=>{const criticalImages=document.querySelectorAll('img[fetchpriority="high"]');criticalImages.forEach(img=>{if(!img.complete){img.loading="eager";loadImage(img)}})});document.addEventListener("mouseover",e=>{if(e.target.matches('a[href*="/blog/"]')){const link=e.target;if(!link.dataset.prefetched){link.dataset.prefetched="true"}}})})();